#!/usr/bin/env node
// Generates src/data/attackTechniques.ts in backend/ and backend-serverless/
// from MITRE ATT&CK Enterprise (github.com/mitre/cti). Re-run when ATT&CK
// ships a new version, then commit both generated files.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SOURCE = 'https://raw.githubusercontent.com/mitre/cti/master/enterprise-attack/enterprise-attack.json';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const targets = ['backend/src/data/attackTechniques.ts', 'backend-serverless/src/data/attackTechniques.ts'];

const res = await fetch(SOURCE);
if (!res.ok) throw new Error(`Download failed: ${res.status} ${res.statusText}`);
const bundle = await res.json();

const techniques = {};
for (const o of bundle.objects) {
  if (o.type !== 'attack-pattern' || o.revoked || o.x_mitre_deprecated) continue;
  const ref = (o.external_references ?? []).find((r) => r.source_name === 'mitre-attack');
  if (!ref?.external_id) continue;
  techniques[ref.external_id] = {
    name: o.name,
    tactics: (o.kill_chain_phases ?? []).filter((p) => p.kill_chain_name === 'mitre-attack').map((p) => p.phase_name),
  };
}

const ids = Object.keys(techniques).sort();
const version = bundle.objects.find((o) => o.type === 'x-mitre-collection')?.x_mitre_version ?? 'unknown';
const body = ids.map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(techniques[id])},`).join('\n');
const file = `// GENERATED by scripts/generate-attack-techniques.mjs from MITRE ATT&CK Enterprise ${version}.
// Do not edit by hand; re-run the script instead.

export interface AttackTechniqueInfo {
  name: string;
  /** Kebab-case tactic short names, e.g. 'credential-access'. */
  tactics: string[];
}

const ATTACK_TECHNIQUES: Record<string, AttackTechniqueInfo> = {
${body}
};

export function techniqueInfo(id: string): AttackTechniqueInfo | null {
  return ATTACK_TECHNIQUES[id.toUpperCase()] ?? null;
}
`;

for (const target of targets) {
  mkdirSync(dirname(join(root, target)), { recursive: true });
  writeFileSync(join(root, target), file);
}
console.log(`Wrote ${ids.length} techniques (ATT&CK ${version}) to ${targets.join(', ')}`);
